{
  "status": "NEEDS_IMPROVEMENT",
  "core_findings": [
    "Electronics has the weakest training separation: its 10th-percentile margin is 0.2522, and negatives outrank positives at 7.9% of valid positions. It also has the strongest item-embedding directional alignment (0.8006), which does not establish low recommendation diversity.",
    "Movies_and_TV and CDs_and_Vinyl show stronger training separation, with negative-win rates of 0.72% and 1.58%; Industrial_and_Scientific is intermediate at 3.65%. Across all four datasets, recent-history removal changes logits substantially more than distant-history removal."
  ],
  "key_implications": [
    "The measured encoder scores are especially sensitive to the last five interactions, although removal comparisons use different sets of changed users.",
    "Electronics combines greater embedding alignment with more weakly separated training comparisons; these measurements do not establish a causal link.",
    "These training diagnostics do not establish validation HR@10 or generalization performance."
  ],
  "evidence": {
    "headline_metrics": {
      "Electronics:embedding_collapse_score": 0.8006,
      "Electronics:pos_neg_margin_p10": 0.2522,
      "Electronics:pos_neg_neg_beats_pos_rate": 0.079,
      "Electronics:pos_neg_small_margin_rate": 0.1267,
      "Electronics:recent_removal_logit_rms": 39.5902,
      "Electronics:distant_removal_logit_rms": 0.499
    },
    "brief_metric_read": {
      "embedding_collapse_score": "Electronics has the highest mean directional alignment; 0.5 represents zero mean cosine.",
      "pos_neg_small_margin_rate": "12.67% of Electronics training comparisons have margins below 0.5.",
      "recent_dependence": "Recent-removal RMS exceeds distant-removal RMS in every dataset; unchanged-history differences are zero."
    }
  }
}
